110: /**
111:  * @internal
112:  * @~English
113:  * @brief Additional contextProfile bit indicating an OpenGL ES context.
114:  *
115:  * This is the same value NVIDIA returns when using an OpenGL ES profile
116:  * of their desktop drivers. However it is not specified in any official
117:  * specification as OpenGL ES does not support the GL_CONTEXT_PROFILE_MASK
118:  * query.
119:  */
120: #define _CONTEXT_ES_PROFILE_BIT 0x4
121: 
122: /**
123:  * @internal
124:  * @~English
125:  * @name Supported Sized Format Macros
126:  *
127:  * These macros describe values that may be used with the sizedFormats
128:  * variable.
129:  */
130: /**@{*/
131: #define _NON_LEGACY_FORMATS 0x1 /*< @internal Non-legacy sized formats are supported. */
132: #define _LEGACY_FORMATS 0x2  /*< @internal Legacy sized formats are supported. */
133: /**
134:  * @internal
135:  * @~English
136:  * @brief All sized formats are supported
137:  */
138: #define _ALL_SIZED_FORMATS (_NON_LEGACY_FORMATS | _LEGACY_FORMATS)
139: #define _NO_SIZED_FORMATS 0 /*< @internal No sized formats are supported. */
140: /**@}*/
141: 
142: /**
143:  * @internal
144:  * @~English
145:  * @brief indicates the profile of the current context.
146:  */
147: static GLint contextProfile = 0;
148: /**
149:  * @internal
150:  * @~English
151:  * @brief Indicates what sized texture formats are supported
152:  *        by the current context.
153:  */
154: static GLint sizedFormats = _ALL_SIZED_FORMATS;
155: static MAYBE_UNUSED GLboolean supportsSwizzle = GL_TRUE;
156: /**
157:  * @internal
158:  * @~English
159:  * @brief Indicates which R16 & RG16 formats are supported by the current
160:  *        context.
161:  */
162: static GLint R16Formats = _KTX_ALL_R16_FORMATS;
163: /**
164:  * @internal
165:  * @~English
166:  * @brief Indicates if the current context supports sRGB textures.
167:  */
168: static GLboolean supportsSRGB = GL_TRUE;
169: /**
170:  * @internal
171:  * @~English
172:  * @brief Indicates if the current context supports cube map arrays.
173:  */
174: static GLboolean supportsCubeMapArrays = GL_FALSE;
175: 
176: /**
177:  * @internal
178:  * @~English
179:  * @brief Indicates if the current context supports cube map arrays.
180:  */
181: static GLboolean supportsMaxLevel = GL_FALSE;
