183: /**
184:  * @internal
185:  * @~English
186:  * @brief Check for existence of OpenGL extension
187:  */
188: static GLboolean
189: hasExtension(const char* extension)
190: {
191:     if (gl.glGetStringi == NULL) {
192:         if (strstr(glGetString(GL_EXTENSIONS), extension) != NULL) {
193:             return GL_TRUE;
194:         } else {
195:             return GL_FALSE;
196:         }
197:     } else {
198:         int i, n;
199: 
200:         glGetIntegerv(GL_NUM_EXTENSIONS, &n);
201:         for (i = 0; i < n; i++) {
202:             if (strcmp((const char*)gl.glGetStringi(GL_EXTENSIONS, i), extension) == 0)
203:                 return GL_TRUE;
204:         }
205:         return GL_FALSE;
206:     }
207: }
208: 
209: /**
210:  * @internal
211:  * @~English
212:  * @brief Discover the capabilities of the current GL context.
213:  *
214:  * Queries the context and sets several the following internal variables
215:  * indicating the capabilities of the context:
216:  *
217:  * @li sizedFormats
218:  * @li supportsSwizzle
219:  * @li supportsSRGB
220:  * @li b16Formats
221:  * @li supportsMaxLevel
222:  */
223: static void
224: discoverContextCapabilities(void)
225: {
226:     GLint majorVersion = 1;
227:     GLint minorVersion = 0;
228: 
229:     if (strstr(glGetString(GL_VERSION), "GL ES") != NULL)
230:         contextProfile = _CONTEXT_ES_PROFILE_BIT;
231:     // MAJOR & MINOR only introduced in GL {,ES} 3.0
232:     glGetIntegerv(GL_MAJOR_VERSION, &majorVersion);
233:     glGetIntegerv(GL_MINOR_VERSION, &minorVersion);
234:     if (glGetError() != GL_NO_ERROR) {
235:         // < v3.0; resort to the old-fashioned way.
236:         if (contextProfile & _CONTEXT_ES_PROFILE_BIT)
237:             sscanf(glGetString(GL_VERSION), "OpenGL ES %d.%d ",
238:                    &majorVersion, &minorVersion);
239:         else
240:             sscanf(glGetString(GL_VERSION), "OpenGL %d.%d ",
241:                    &majorVersion, &minorVersion);
242:     }
243:     if (contextProfile & _CONTEXT_ES_PROFILE_BIT) {
244:         if (majorVersion < 3) {
245:             supportsSwizzle = GL_FALSE;
246:             sizedFormats = _NO_SIZED_FORMATS;
247:             R16Formats = _KTX_NO_R16_FORMATS;
248:             supportsSRGB = GL_FALSE;
249:             // These things could be found by dlsym when, e.g. the same driver
250:             // supports ES1, ES2 and ES3. For all but Tex*3D, there's no
251:             // corresponding extension whose presence we could check. Just zero
252:             // the pointers to prevent use.
253:             gl.glGetStringi = NULL;
254:             gl.glCompressedTexImage1D = NULL;
255:             gl.glTexStorage1D = NULL;
256:             gl.glTexStorage2D = NULL;
257:             gl.glTexStorage3D = NULL;
258:             if (!hasExtension("GL_OES_texture_3D")) {
259:                 gl.glCompressedTexImage3D = NULL;
260:                 gl.glCompressedTexSubImage3D = NULL;
261:                 gl.glTexImage3D = NULL;
262:                 gl.glTexSubImage3D = NULL;
263:             }
264:             if (majorVersion < 2)
265:                 gl.glGenerateMipmap = NULL;
266: 
267:         } else {
268:             sizedFormats = _NON_LEGACY_FORMATS;
269:             if (hasExtension("GL_EXT_texture_cube_map_array")) {
270:                 supportsCubeMapArrays = GL_TRUE;
271:             }
272:             supportsMaxLevel = GL_TRUE;
273:         }
274:         if (hasExtension("GL_OES_required_internalformat")) {
275:             sizedFormats |= _ALL_SIZED_FORMATS;
276:         }
277:         // There are no OES extensions for sRGB textures or R16 formats.
278:     } else {
279:         // PROFILE_MASK was introduced in OpenGL 3.2.
280:         // Profiles: CONTEXT_CORE_PROFILE_BIT 0x1,
281:         //           CONTEXT_COMPATIBILITY_PROFILE_BIT 0x2.
282:         glGetIntegerv(GL_CONTEXT_PROFILE_MASK, &contextProfile);
283:         if (glGetError() == GL_NO_ERROR) {
284:             // >= 3.2
285:             if (majorVersion == 3 && minorVersion < 3)
286:                 supportsSwizzle = GL_FALSE;
287:             if ((contextProfile & GL_CONTEXT_CORE_PROFILE_BIT))
288:                 sizedFormats &= ~_LEGACY_FORMATS;
289:             if (majorVersion >= 4)
290:                 supportsCubeMapArrays = GL_TRUE;
291:             supportsMaxLevel = GL_TRUE;
292:         } else {
293:             // < 3.2
294:             contextProfile = GL_CONTEXT_COMPATIBILITY_PROFILE_BIT;
295:             supportsSwizzle = GL_FALSE;
296:             // sRGB textures introduced in 2.0
297:             if (majorVersion < 2 && !hasExtension("GL_EXT_texture_sRGB")) {
298:                 supportsSRGB = GL_FALSE;
299:             }
300:             // R{,G]16 introduced in 3.0; R{,G}16_SNORM introduced in 3.1.
301:             if (majorVersion == 3) {
302:                 if (minorVersion == 0)
303:                     R16Formats &= ~_KTX_R16_FORMATS_SNORM;
304:                 if (minorVersion < 1) {
305:                     if (hasExtension("GL_ARB_texture_query_levels"))
306:                         supportsMaxLevel = GL_TRUE;
307:                 } else {
308:                   supportsMaxLevel = GL_TRUE;
309:                 }
310:             } else if (hasExtension("GL_ARB_texture_rg")) {
311:                 R16Formats &= ~_KTX_R16_FORMATS_SNORM;
312:             } else {
313:                 R16Formats = _KTX_NO_R16_FORMATS;
314:             }
315:         }
316:         if (!supportsCubeMapArrays) {
317:             if (hasExtension("GL_ARB_texture_cube_map_array")) {
318:                 supportsCubeMapArrays = GL_TRUE;
319:             }
320:         }
321:     }
322: }
323: 
324: #if SUPPORT_LEGACY_FORMAT_CONVERSION
325: /**
326:  * @internal
327:  * @~English
328:  * @brief Convert deprecated legacy-format texture to modern format.
329:  *
330:  * The function sets the GL_TEXTURE_SWIZZLEs necessary to get the same
331:  * behavior as the legacy format.
332:  *
333:  * @param[in] target       texture target on which the swizzle will
334:  *                          be set.
335:  * @param[in,out] pFormat  pointer to variable holding the base format of the
336:  *                          texture. The new base format is written here.
337:  * @param[in,out] pInternalformat  pointer to variable holding the
338:  *                                  internalformat of the texture. The new
339:  *                                  internalformat is written here.
340:  * @return void unrecognized formats will be passed on to OpenGL. Any loading
341:  *              error that arises will be handled in the usual way.
342:  */
343: static void convertFormat(GLenum target, GLenum* pFormat, GLenum* pInternalformat) {
344:     switch (*pFormat) {
345:       case GL_ALPHA:
346:         {
347:           GLint swizzle[] = {GL_ZERO, GL_ZERO, GL_ZERO, GL_RED};
348:           *pFormat = GL_RED;
349:           glTexParameteriv(target, GL_TEXTURE_SWIZZLE_RGBA, swizzle);
350:           switch (*pInternalformat) {
351:             case GL_ALPHA:
352:             case GL_ALPHA4_EXT:
353:             case GL_ALPHA8_EXT:
354:               *pInternalformat = GL_R8;
355:               break;
356:             case GL_ALPHA12_EXT:
357:             case GL_ALPHA16_EXT:
358:               *pInternalformat = GL_R16;
359:               break;
360:           }
361:         }
362:       case GL_LUMINANCE:
363:         {
364:           GLint swizzle[] = {GL_RED, GL_RED, GL_RED, GL_ONE};
365:           *pFormat = GL_RED;
366:           glTexParameteriv(target, GL_TEXTURE_SWIZZLE_RGBA, swizzle);
367:           switch (*pInternalformat) {
368:             case GL_LUMINANCE:
369:             case GL_LUMINANCE4_EXT:
370:             case GL_LUMINANCE8_EXT:
371:               *pInternalformat = GL_R8;
372:               break;
373:             case GL_LUMINANCE12_EXT:
374:             case GL_LUMINANCE16_EXT:
375:               *pInternalformat = GL_R16;
376:               break;
377: #if 0
378:             // XXX Must avoid setting TEXTURE_SWIZZLE in these cases
379:             // XXX Must manually swizzle.
380:             case GL_SLUMINANCE:
381:             case GL_SLUMINANCE8:
382:               *pInternalformat = GL_SRGB8;
383:               break;
384: #endif
385:           }
386:           break;
387:         }
388:       case GL_LUMINANCE_ALPHA:
389:         {
390:           GLint swizzle[] = {GL_RED, GL_RED, GL_RED, GL_GREEN};
391:           *pFormat = GL_RG;
392:           glTexParameteriv(target, GL_TEXTURE_SWIZZLE_RGBA, swizzle);
393:           switch (*pInternalformat) {
394:             case GL_LUMINANCE_ALPHA:
395:             case GL_LUMINANCE4_ALPHA4_EXT:
396:             case GL_LUMINANCE6_ALPHA2_EXT:
397:             case GL_LUMINANCE8_ALPHA8_EXT:
398:               *pInternalformat = GL_RG8;
399:               break;
400:             case GL_LUMINANCE12_ALPHA4_EXT:
401:             case GL_LUMINANCE12_ALPHA12_EXT:
402:             case GL_LUMINANCE16_ALPHA16_EXT:
403:               *pInternalformat = GL_RG16;
404:               break;
405: #if 0
406:             // XXX Must avoid setting TEXTURE_SWIZZLE in these cases
407:             // XXX Must manually swizzle.
408:             case GL_SLUMINANCE_ALPHA_EXT:
409:             case GL_SLUMINANCE8_ALPHA8_EXT:
410:               *pInternalformat = GL_SRGB8_ALPHA8;
411:               break;
412: #endif
413:           }
414:           break;
415:         }
416:       case GL_INTENSITY:
417:         {
418:           GLint swizzle[] = {GL_RED, GL_RED, GL_RED, GL_RED};
419:           *pFormat = GL_RED;
420:           glTexParameteriv(target, GL_TEXTURE_SWIZZLE_RGBA, swizzle);
421:           switch (*pInternalformat) {
422:             case GL_INTENSITY:
423:             case GL_INTENSITY4_EXT:
424:             case GL_INTENSITY8_EXT:
425:               *pInternalformat = GL_R8;
426:               break;
427:             case GL_INTENSITY12_EXT:
428:             case GL_INTENSITY16_EXT:
429:               *pInternalformat = GL_R16;
430:               break;
431:           }
432:           break;
433:         }
434:       default:
435:         break;
436:     }
437: }
438: #endif /* SUPPORT_LEGACY_FORMAT_CONVERSION */
