460: KTX_error_code
461: texImage1DCallback(int miplevel, int face,
462:                    int width, int height,
463:                    int depth,
464:                    ktx_uint64_t faceLodSize,
465:                    void* pixels, void* userdata)
466: {
467:     ktx_cbdata* cbData = (ktx_cbdata*)userdata;
468:     UNUSED(faceLodSize);
469:     UNUSED(depth);
470:     UNUSED(height);
471: 
472:     assert(gl.glTexImage1D != NULL);
473:     gl.glTexImage1D(cbData->glTarget + face, miplevel,
474:                    cbData->glInternalformat, width, 0,
475:                    cbData->glFormat, cbData->glType, pixels);
476: 
477:     if ((cbData->glError = glGetError()) == GL_NO_ERROR) {
478:         return KTX_SUCCESS;
479:     } else {
480:         return KTX_GL_ERROR;
481:     }
482: }
