484: KTX_error_code
485: compressedTexImage1DCallback(int miplevel, int face,
486:                              int width, int height,
487:                              int depth,
488:                              ktx_uint64_t faceLodSize,
489:                              void* pixels, void* userdata)
490: {
491:     ktx_cbdata* cbData = (ktx_cbdata*)userdata;
492:     UNUSED(depth);
493:     UNUSED(height);
494: 
495:     if (faceLodSize > UINT32_MAX)
496:         return KTX_INVALID_OPERATION; // Too big for OpenGL {,ES}.
497: 
498:     assert(gl.glCompressedTexImage1D != NULL);
499:     gl.glCompressedTexImage1D(cbData->glTarget + face, miplevel,
500:                              cbData->glInternalformat, width, 0,
501:                              (ktx_uint32_t)faceLodSize, pixels);
502: 
503:     if ((cbData->glError = glGetError()) == GL_NO_ERROR) {
504:         return KTX_SUCCESS;
505:     } else {
506:         return KTX_GL_ERROR;
507:     }
508: }
