510: KTX_error_code
511: texImage2DCallback(int miplevel, int face,
512:                    int width, int height,
513:                    int depth,
514:                    ktx_uint64_t faceLodSize,
515:                    void* pixels, void* userdata)
516: {
517:     ktx_cbdata* cbData = (ktx_cbdata*)userdata;
518:     UNUSED(depth);
519:     UNUSED(faceLodSize);
520: 
521:     glTexImage2D(cbData->glTarget + face, miplevel,
522:                  cbData->glInternalformat, width,
523:                  cbData->numLayers == 0 ? (GLuint)height : cbData->numLayers, 0,
524:                  cbData->glFormat, cbData->glType, pixels);
525: 
526:     if ((cbData->glError = glGetError()) == GL_NO_ERROR) {
527:         return KTX_SUCCESS;
