533: 
534: KTX_error_code
535: compressedTexImage2DCallback(int miplevel, int face,
536:                              int width, int height,
537:                              int depth,
538:                              ktx_uint64_t faceLodSize,
539:                              void* pixels, void* userdata)
540: {
541:     ktx_cbdata* cbData = (ktx_cbdata*)userdata;
542:     GLenum glerror;
543: #if SUPPORT_SOFTWARE_ETC_UNPACK
544:     KTX_error_code result;
545: #endif
546:     UNUSED(depth);
547: 
548:     if (faceLodSize > UINT32_MAX)
549:         return KTX_INVALID_OPERATION; // Too big for OpenGL {,ES}.
550: 
551:     // It is simpler to just attempt to load the format, rather than divine
552:     // which formats are supported by the implementation. In the event of an
553:     // error, software unpacking can be attempted.
554:     glCompressedTexImage2D(cbData->glTarget + face, miplevel,
555:                            cbData->glInternalformat, width,
556:                            cbData->numLayers == 0 ? (GLuint)height : cbData->numLayers,
557:                            0,
558:                            (ktx_uint32_t)faceLodSize, pixels);
559: 
560:     glerror = glGetError();
561: #if SUPPORT_SOFTWARE_ETC_UNPACK
562:     // Renderion is returning INVALID_VALUE. Oops!!
563:     if ((glerror == GL_INVALID_ENUM || glerror == GL_INVALID_VALUE)
564:         && (cbData->glInternalformat == GL_ETC1_RGB8_OES
565:             || (cbData->glInternalformat >= GL_COMPRESSED_R11_EAC
566:                 && cbData->glInternalformat <= GL_COMPRESSED_SRGB8_ALPHA8_ETC2_EAC)
567:             ))
568:     {
569:         GLubyte* unpacked;
570:         GLenum format, internalformat, type;
571: 
572:         result = _ktxUnpackETC((GLubyte*)pixels, cbData->glInternalformat,
573:                                   width, height, &unpacked,
574:                                   &format, &internalformat,
575:                                   &type, R16Formats, supportsSRGB);
576:         if (result != KTX_SUCCESS) {
577:             return result;
578:         }
579:         if (!(sizedFormats & _NON_LEGACY_FORMATS)) {
580:             if (internalformat == GL_RGB8)
581:                 internalformat = GL_RGB;
582:             else if (internalformat == GL_RGBA8)
583:                 internalformat = GL_RGBA;
584:         }
585:         glTexImage2D(cbData->glTarget + face, miplevel,
586:                      internalformat, width,
587:                      cbData->numLayers == 0 ? (GLuint)height : cbData->numLayers, 0,
588:                      format, type, unpacked);
589: 
590:         free(unpacked);
591:         glerror = glGetError();
592:     }
593: #endif
594: 
595:     if ((cbData->glError = glerror) == GL_NO_ERROR) {
596:         return KTX_SUCCESS;
597:     } else {
598:         return KTX_GL_ERROR;
599:     }
600: }
