655: /**
656:  * @memberof ktxTexture @private
657:  * @~English
658:  * @brief Do the common work of creating a GL texture object from a
659:  *        ktxTexture object.
660:  *
661:  * Sets the texture object's GL_TEXTURE_MAX_LEVEL parameter according to the
662:  * number of levels in the KTX data, provided the context supports this feature.
663:  *
664:  * Unpacks compressed GL_ETC1_RGB8_OES and GL_ETC2_* format
665:  * textures in software when the format is not supported by the GL context,
666:  * provided the library has been compiled with SUPPORT_SOFTWARE_ETC_UNPACK
667:  * defined as 1.
668:  *
669:  * It will also convert textures with legacy formats to their modern equivalents
670:  * when the format is not supported by the GL context, provided the library
671:  * has been compiled with SUPPORT_LEGACY_FORMAT_CONVERSION defined as 1.
672:  *
673:  * @param[in] This          handle of the ktxTexture to upload.
674:  * @param[in] formatInfo    pointer to a ktx_glformatinfo structure providing
675:  *                          information about the texture format.
676:  * @param[in,out] pTexture  name of the GL texture object to load. If NULL or if
677:  *                          <tt>*pTexture == 0</tt> the function will generate
678:  *                          a texture name. The function binds either the
679:  *                          generated name or the name given in @p *pTexture
680:  *                          to the texture target returned in @p *pTarget,
681:  *                          before loading the texture data. If @p pTexture
682:  *                          is not NULL and a name was generated, the generated
683:  *                          name will be returned in *pTexture.
684:  * @param[out] pTarget      @p *pTarget is set to the texture target used. The
685:  *                          target is chosen based on the file contents.
686:  * @param[out] pGlerror     @p *pGlerror is set to the value returned by
687:  *                          glGetError when this function returns the error
688:  *                          KTX_GL_ERROR. pGlerror can be NULL.
689:  *
690:  * @return  KTX_SUCCESS on success, other KTX_* enum values on error.
691:  *
692:  * @exception KTX_INVALID_VALUE @p This or @p target is @c NULL or the size of
693:  *                              a mip level is greater than the size of the
694:  *                              preceding level.
695:  * @exception KTX_GL_ERROR      A GL error was raised by glBindTexture,
696:  *                              glGenTextures or gl*TexImage*. The GL error
697:  *                              will be returned in @p *glerror, if glerror
698:  *                              is not @c NULL.
699:  * @exception KTX_UNSUPPORTED_TEXTURE_TYPE The type of texture is not supported
700:  *                                         by the current OpenGL context.
701:  */
702: /* [loadGLTexture] */
703: KTX_error_code
704: ktxTexture_GLUploadPrivate(ktxTexture* This, ktx_glformatinfo* formatInfo,
705:                            GLuint* pTexture, GLenum* pTarget, GLenum* pGlerror)
706: {
707:     GLuint                texname;
708:     GLenum                target = GL_TEXTURE_2D;
709:     int                   texnameUser;
710:     KTX_error_code        result = KTX_SUCCESS;
711:     ktx_cbdata            cbData;
712:     PFNKTXITERCB          iterCb = NULL;
713:     int                   dimensions;
714: 
715:     if (pGlerror)
716:         *pGlerror = GL_NO_ERROR;
717: 
718:     assert(This && pTarget);
719: 
720:     if (contextProfile == 0)
721:         discoverContextCapabilities();
722: 
723:     texnameUser = pTexture && *pTexture;
724:     if (texnameUser) {
725:         texname = *pTexture;
726:     } else {
727:         glGenTextures(1, &texname);
728:     }
729: 
730:     cbData.glFormat = formatInfo->glFormat;
731:     cbData.glInternalformat = formatInfo->glInternalformat;
732:     cbData.glType = formatInfo->glType;
733: 
734:     dimensions = This->numDimensions;
735:     if (This->isArray) {
736:         dimensions += 1;
737:         if (This->numFaces == 6) {
738:             /* ktxCheckHeader1_ should have caught this. */
739:             assert(This->numDimensions == 2);
740:             target = GL_TEXTURE_CUBE_MAP_ARRAY;
741:         } else {
742:             switch (This->numDimensions) {
743:               case 1: target = GL_TEXTURE_1D_ARRAY; break;
744:               case 2: target = GL_TEXTURE_2D_ARRAY; break;
745:               /* _ktxCheckHeader should have caught this. */
746:               default: assert(KTX_TRUE);
747:             }
748:         }
749:         cbData.numLayers = This->numLayers;
750:     } else {
751:         if (This->numFaces == 6) {
752:             /* ktxCheckHeader1_ should have caught this. */
753:             assert(This->numDimensions == 2);
754:             target = GL_TEXTURE_CUBE_MAP;
755:         } else {
756:             switch (This->numDimensions) {
757:               case 1: target = GL_TEXTURE_1D; break;
758:               case 2: target = GL_TEXTURE_2D; break;
759:               case 3: target = GL_TEXTURE_3D; break;
760:               /* _ktxCheckHeader shold have caught this. */
761:               default: assert(KTX_TRUE);
762:             }
763:         }
764:         cbData.numLayers = 0;
765:     }
766: 
767:     if (target == GL_TEXTURE_1D &&
768:         ((This->isCompressed && (gl.glCompressedTexImage1D == NULL)) ||
769:          (!This->isCompressed && (gl.glTexImage1D == NULL))))
770:     {
771:         return KTX_UNSUPPORTED_TEXTURE_TYPE;
772:     }
773: 
774:     /* Reject 3D texture if unsupported. */
775:     if (target == GL_TEXTURE_3D &&
776:         ((This->isCompressed && (gl.glCompressedTexImage3D == NULL)) ||
777:          (!This->isCompressed && (gl.glTexImage3D == NULL))))
778:     {
779:         return KTX_UNSUPPORTED_TEXTURE_TYPE;
780:     }
781: 
782:     /* Reject cube map arrays if not supported. */
783:     if (target == GL_TEXTURE_CUBE_MAP_ARRAY && !supportsCubeMapArrays) {
784:         return KTX_UNSUPPORTED_TEXTURE_TYPE;
785:     }
786: 
787:     /* XXX Need to reject other array textures & cube maps if not supported. */
788: 
789:     switch (dimensions) {
790:       case 1:
791:         iterCb = This->isCompressed
792:                   ? compressedTexImage1DCallback : texImage1DCallback;
793:         break;
794:       case 2:
795:         iterCb = This->isCompressed
796:                   ? compressedTexImage2DCallback : texImage2DCallback;
797:             break;
798:       case 3:
799:         iterCb = This->isCompressed
800:                   ? compressedTexImage3DCallback : texImage3DCallback;
801:         break;
802:       default:
803:             assert(KTX_TRUE);
804:     }
805: 
806:     glBindTexture(target, texname);
807: 
808:     // Prefer glGenerateMipmaps over GL_GENERATE_MIPMAP
809:     if (This->generateMipmaps && (gl.glGenerateMipmap == NULL)) {
810:         glTexParameteri(target, GL_GENERATE_MIPMAP, GL_TRUE);
811:     }
812: 
813:     if (!This->generateMipmaps && supportsMaxLevel)
814:         glTexParameteri(target, GL_TEXTURE_MAX_LEVEL, This->numLevels - 1);
815: 
816:     if (target == GL_TEXTURE_CUBE_MAP) {
817:         cbData.glTarget = GL_TEXTURE_CUBE_MAP_POSITIVE_X;
818:     } else {
819:         cbData.glTarget = target;
820:     }
821: 
822:     if (!This->isCompressed) {
823: #if SUPPORT_LEGACY_FORMAT_CONVERSION
824:         // If sized legacy formats are supported there is no need to convert.
825:         // If only unsized formats are supported, there is no point in
826:         // converting as the modern formats aren't supported either.
827:         if (sizedFormats == _NON_LEGACY_FORMATS && supportsSwizzle) {
828:             convertFormat(target, &cbData.glFormat, &cbData.glInternalformat);
829:         } else if (sizedFormats == _NO_SIZED_FORMATS)
830:             cbData.glInternalformat = formatInfo->glBaseInternalformat;
831: #else
832:         // When no sized formats are supported, or legacy sized formats are not
833:         // supported, must change internal format.
834:         if (sizedFormats == _NO_SIZED_FORMATS
835:             || (!(sizedFormats & _LEGACY_FORMATS) &&
836:                 (formatInfo->glBaseInternalformat == GL_ALPHA
837:                 || formatInfo->glBaseInternalformat == GL_LUMINANCE
838:                 || formatInfo->glBaseInternalformat == GL_LUMINANCE_ALPHA
839:                 || formatInfo->glBaseInternalformat == GL_INTENSITY))) {
840:             cbData.glInternalformat = formatInfo->glBaseInternalformat;
841:         }
842: #endif
843:     }
844: 
845:     if (ktxTexture_isActiveStream(ktxTexture(This)))
846:         result = ktxTexture_IterateLoadLevelFaces(This, iterCb, &cbData);
847:     else
848:         result = ktxTexture_IterateLevelFaces(This, iterCb, &cbData);
849: 
850:     /* GL errors are the only reason for failure. */
851:     if (result != KTX_SUCCESS && cbData.glError != GL_NO_ERROR) {
852:         if (pGlerror)
853:             *pGlerror = cbData.glError;
854:     }
855: 
856:     if (result == KTX_SUCCESS)
857:     {
858:         // Prefer glGenerateMipmaps over GL_GENERATE_MIPMAP
859:         if (This->generateMipmaps && gl.glGenerateMipmap) {
860:             gl.glGenerateMipmap(target);
861:         }
862:         *pTarget = target;
863:         if (pTexture) {
864:             *pTexture = texname;
865:         }
866:     } else if (!texnameUser) {
867:         glDeleteTextures(1, &texname);
868:     }
