923:     GLint                 previousUnpackAlignment;
924:     KTX_error_code        result = KTX_SUCCESS;
925:     ktx_glformatinfo      formatInfo;
926: 
927:     if (!This) {
928:         return KTX_INVALID_VALUE;
929:     }
930: 
931:     if (!pTarget) {
932:         return KTX_INVALID_VALUE;
933:     }
934: 
935:     result = ktxLoadOpenGL(NULL);
